(function(){
  var $=function(id){return document.getElementById(id)};
  var TAG=/#[\p{L}\p{N}_]+/gu;
  // U+2063 invisible separator. Instagram strips lines that are truly empty,
  // so a blank line needs one invisible character to survive.
  var INV='\u2063';

  function run(){
    var src=$('cap').value;
    var tags=src.match(TAG)||[];
    var body=src, tail='';
    var place=$('place').value;
    if(place!=='keep'){
      body=src.replace(TAG,'').replace(/[ \t]{2,}/g,' ');
      body=body.split('\n').map(function(l){return l.replace(/\s+$/,'')}).join('\n').replace(/\n{3,}/g,'\n\n').trim();
      if(place==='end') tail='\n\n'+tags.join(' ');
      if(place==='hidden') tail='\n'+['.','.','.','.','.'].join('\n')+'\n'+tags.join(' ');
    }
    var lines=body.split('\n');
    var sp=$('space').value;
    if(sp==='tight') lines=lines.filter(function(l){return l.trim()!==''});
    if(sp==='airy'){
      var a=[]; lines.filter(function(l){return l.trim()!==''}).forEach(function(l,i,arr){
        a.push(l); if(i<arr.length-1) a.push('');
      }); lines=a;
    }
    var outText=lines.join('\n')+tail;
    // Applied to the whole caption, tail included. Doing it to the body
    // alone left the gap above a moved hashtag block unprotected, so
    // Instagram collapsed the one blank line the user could actually see.
    if($('invisible').checked){
      outText=outText.split('\n').map(function(l){ return l.trim()===''?INV:l; }).join('\n');
    }
    $('cap').dataset.out=outText;

    var chars=Array.from(outText).length;
    $('nchar').textContent=chars;
    $('nline').textContent=lines.length;
    $('ntag').textContent = place==='strip' ? 0 : tags.length;

    // preview with the Instagram fold drawn in at 125 characters
    var shown=outText.replace(new RegExp(INV,'g'),'');
    var cut=125, before=shown.slice(0,cut), after=shown.slice(cut);
    $('prev').innerHTML='<div class="cf-head">How it looks in the feed</div><div class="cf-body">'+
      esc(before)+ (after ? '<div class="cf-fold">everything below here is hidden behind "more"</div>'+esc(after) : '')+
      '</div>';
    $('note').textContent = $('invisible').checked
      ? 'Blank lines carry one invisible character, which is what stops Instagram collapsing them. Paste the copied version rather than retyping it.'
      : 'Blank lines are plain, so Instagram may collapse them. Tick the box above to protect them.';
    if(window.WT) WT.resize();
  }
  function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

  ['cap','place','space','invisible'].forEach(function(id){
    $(id).addEventListener('input',run); $(id).addEventListener('change',run);
  });
  $('copy').addEventListener('click',function(){
    var ok=WT.copy($('cap').dataset.out||'');
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy caption'},1400);
  });
  $('copytags').addEventListener('click',function(){
    var ok=WT.copy(($('cap').value.match(TAG)||[]).join(' '));
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy hashtags only'},1400);
  });
  $('clear').addEventListener('click',function(){ $('cap').value=''; run(); });
  run();
})();
